// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timeJump1, uint256 timeJump2) public {
        timeJump1 = bound(timeJump1, 1, 1000);
        timeJump2 = bound(timeJump2, 1, 1000);

        // First successful fallback call
        vm.warp(block.timestamp + timeJump1);
        vm.deal(address(this), 10 ether);
        (bool success1, ) = address(c).call{value: 10 ether}("");

        // Second fallback call without advancing time (should pass in reference, fail in mutant)
        (bool success2, ) = address(c).call{value: 10 ether}("");

        // General rule: after a successful fallback, calling again at the same timestamp should revert
        // because pastBlockTime is set to block.timestamp + 1, making block.timestamp < pastBlockTime false
        assertTrue(success1 && !success2);
    }
}

